insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level, question, options, correct_index, explanation, topic, is_general, semester, units)
values
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\vec u = 2i + j - 4k$ and $\vec v = 3i - 2j + k$, find $\vec u + \vec v$.', '["$5i - j - 3k$", "$-i + 3j - 5k$", "$5i + j - 3k$", "$5i - j + 3k$"]'::jsonb, 0, 'Add corresponding components: $(2+3)i+(1-2)j+(-4+1)k = 5i - j - 3k$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\vec u = 2i + j - 4k$ and $\vec v = 3i - 2j + k$, find $\vec u - \vec v$.', '["$-i + 3j - 5k$", "$5i - j - 3k$", "$-i - 3j - 5k$", "$i + 3j - 5k$"]'::jsonb, 0, 'Subtract corresponding components: $(2-3)i+(1-(-2))j+(-4-1)k = -i + 3j - 5k$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\vec u = 2i + j - 4k$ and $\vec v = 3i - 2j + k$, find $3\vec v - \vec u$.', '["$7i - 7j + 7k$", "$7i + 7j + 7k$", "$-7i - 7j + 7k$", "$7i - 7j - 7k$"]'::jsonb, 0, '$3\vec v = 9i-6j+3k$, so $3\vec v - \vec u = (9-2)i+(-6-1)j+(3-(-4))k = 7i-7j+7k$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec u = 2i + j - 4k$ and $\vec v = 3i - 2j + k$, evaluate $-6\vec u + \tfrac13\vec v$.', '["$-11i - \\tfrac{20}{3}j + \\tfrac{73}{3}k$", "$-11i + \\tfrac{20}{3}j - \\tfrac{73}{3}k$", "$11i - \\tfrac{20}{3}j + \\tfrac{73}{3}k$", "$-11i - \\tfrac{20}{3}j - \\tfrac{73}{3}k$"]'::jsonb, 0, '$-6\vec u = -12i-6j+24k$ and $\tfrac13\vec v = i-\tfrac23 j+\tfrac13 k$. Adding gives $-11i-\tfrac{20}{3}j+\tfrac{73}{3}k$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec a = 3i + 2j + 4k$ and $\vec b = -4i + 2j + 5k$, then $3\vec a - 5\vec b$ equals', '["$29i - 4j - 13k$", "$-29i - 4j - 13k$", "$29i + 4j + 13k$", "$29i + 4j - 13k$"]'::jsonb, 0, '$3\vec a = 9i+6j+12k$ and $5\vec b=-20i+10j+25k$, so $3\vec a-5\vec b = (9+20)i+(6-10)j+(12-25)k = 29i-4j-13k$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The sum of the vectors $\vec{AB}, -\vec{CB}, \vec{DA}$ and $2\vec{CD}$ is', '["$\\vec{CD}$", "$\\vec{AC}$", "$\\vec{BD}$", "$\\vec{BC}$"]'::jsonb, 0, 'Write every vector as a difference of position vectors and simplify: $\vec{AB}-\vec{CB}+\vec{DA}+2\vec{CD} = (B-A)-(B-C)+(A-D)+2(D-C) = D - C = \vec{CD}$. (Verified by assigning random coordinates to $A,B,C,D$ and checking numerically.)', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The sum of the vectors $2\vec{OA}, 4\vec{BC}, \vec{OA}, \vec{AB}$ and $3\vec{OB}$ is', '["$4\\vec{OC}$", "$6\\vec{OB}$", "$3\\vec{OC}$", "$4\\vec{OB}$"]'::jsonb, 0, 'Writing each vector as a position-vector difference: $2(A-O)+4(C-B)+(A-O)+(B-A)+3(B-O) = 4(C-O) = 4\vec{OC}$. (Confirmed numerically with random points $O,A,B,C$.)', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The sum of the vectors $\vec{YA}, \vec{XY}, -\vec{ZY}$ and $\vec{ZX}$ is', '["$\\vec{YA}$", "$\\vec{XY}$", "$\\vec{ZX}$", "$\\vec{YZ}$"]'::jsonb, 0, '$\vec{XY}+\vec{ZX}=\vec{ZY}$, so $\vec{XY}-\vec{ZY}+\vec{ZX} = \vec{ZY}-\vec{ZY}=\vec 0$. Hence the whole sum reduces to $\vec{YA}+\vec 0=\vec{YA}$. (Confirmed numerically.)', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If the magnitudes of $3i + j + 5k$ and $2\lambda i + j - k$ are equal, then $\lambda$ equals', '["$\\pm\\dfrac{\\sqrt{33}}{2}$", "$\\pm\\dfrac{3}{2}$", "$\\pm\\dfrac{3}{\\sqrt2}$", "$\\pm\\dfrac{2}{3}$"]'::jsonb, 0, '$|3i+j+5k|=\sqrt{35}$ and $|2\lambda i+j-k|=\sqrt{4\lambda^2+2}$. Setting $35=4\lambda^2+2$ gives $\lambda^2=33/4$, so $\lambda=\pm\sqrt{33}/2$.', 'Geometric representation of vectors, components and direction cosines', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The direction cosines of $-2i + 4j - 3k$ are', '["$\\dfrac{1}{\\sqrt{29}}(-2i+4j-3k)$", "$\\dfrac{1}{\\sqrt{29}}(2i+4j-3k)$", "$\\dfrac{1}{\\sqrt{29}}(2i-4j-3k)$", "$\\sqrt{29}(-2i+4j+3k)$"]'::jsonb, 0, '$|{-2i+4j-3k}| = \sqrt{4+16+9}=\sqrt{29}$. Dividing the vector by its magnitude gives the direction cosines $\dfrac{1}{\sqrt{29}}(-2i+4j-3k)$.', 'Geometric representation of vectors, components and direction cosines', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The direction cosine along the $y$-axis of the vector $2i - 3j + 6k$ is', '["$-\\dfrac{3}{7}$", "$\\dfrac{6}{7}$", "$\\dfrac{2}{\\sqrt{11}}$", "$-\\dfrac{3}{\\sqrt{11}}$"]'::jsonb, 0, '$|2i-3j+6k|=\sqrt{4+9+36}=7$, so the direction cosines are $(2/7,-3/7,6/7)$; the $y$-component is $-3/7$.', 'Geometric representation of vectors, components and direction cosines', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Determine $\lambda$ so that $2i - \lambda j + k$ and $4i - 2j - 2k$ are perpendicular.', '["$-3$", "$3$", "$6$", "$-6$"]'::jsonb, 0, 'Perpendicular vectors have zero dot product: $(2)(4)+(-\lambda)(-2)+(1)(-2)=6+2\lambda=0$, so $\lambda=-3$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $t$ for which the vectors $2i + tj - k$ and $-4i + 2j + 2k$ are parallel.', '["$-1$", "$1$", "$-2$", "$2$"]'::jsonb, 0, 'Vectors are parallel iff their cross product vanishes. $(2,t,-1)\times(-4,2,2) = (2t+2,\,0,\,4t+4)$, which is zero only when $t=-1$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The value(s) of $t$ for which $2i + tj + 5k$ and $-6i + 9j - 15k$ are parallel is/are', '["$-3$", "$3$", "$9$", "$2$"]'::jsonb, 0, 'For parallel vectors the cross product is zero; solving $(2,t,5)\times(-6,9,-15)=\vec0$ gives $(t+3)^2=0$, so $t=-3$ (a repeated root).', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The angle between the vectors $\vec a = 2i - 3j + 5k$ and $\vec b = -6i + 9j - 15k$ is', '["$\\pi$", "$\\pi/6$", "$\\pi/4$", "$\\dfrac{1}{\\sqrt{29}}(-2i+4j-3k)$"]'::jsonb, 0, 'Since $\vec b = -3\vec a$, the vectors are anti-parallel: $\cos\theta = \dfrac{\vec a\cdot\vec b}{|\vec a||\vec b|} = -1$, so $\theta=\pi$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The angle between the vectors $\vec a = i + 2j - 2k$ and $\vec b = -2i - 4j + 4k$ is', '["$\\pi$", "$\\pi/2$", "$\\pi/3$", "$\\pi/4$"]'::jsonb, 0, 'Since $\vec b = -2\vec a$, the two vectors point in opposite directions, so $\cos\theta=-1$ and $\theta=\pi$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the projection of $\vec v = -i + 2j + 3k$ onto $\vec w = 2i - j - 4k$.', '["$-\\dfrac{16}{\\sqrt{21}}$", "$\\dfrac{16}{\\sqrt{14}}$", "$\\dfrac{16\\sqrt{21}}{21}$", "$-16$"]'::jsonb, 0, 'Projection $= \dfrac{\vec v\cdot\vec w}{|\vec w|}$. Here $\vec v\cdot\vec w = -2-2-12=-16$ and $|\vec w|=\sqrt{4+1+16}=\sqrt{21}$, giving $-16/\sqrt{21}$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', '$2j \wedge i$ equals', '["$-2k$", "$2k$", "$k$", "$0$"]'::jsonb, 0, 'Since $j\wedge i = -k$ (right-hand rule reversed), $2j\wedge i = -2k$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The sine of the angle between $i + 2j + k$ and $i + j - k$ is', '["$\\dfrac{\\sqrt7}{3}$", "$3\\sqrt2$", "$\\sqrt{14}$", "$\\dfrac{\\sqrt2}{3}$"]'::jsonb, 0, '$(i+2j+k)\times(i+j-k) = -3i+2j-k$, with magnitude $\sqrt{14}$. Since $|i+2j+k|=\sqrt6$ and $|i+j-k|=\sqrt3$, $\sin\theta = \sqrt{14}/\sqrt{18} = \sqrt7/3$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The vector product of $2i + j - k$ and $i - j + 2k$ is', '["$i - 5j - 3k$", "$i - 3j - 3k$", "$-3i - j - 2k$", "$-i + 3j + 3k$"]'::jsonb, 0, '$(2,1,-1)\times(1,-1,2) = (1\cdot2-(-1)(-1),\,(-1)(1)-(2)(2),\,(2)(-1)-(1)(1)) = (1,-5,-3)$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec a = -i + 2j + k$ and $\vec b = 3i + 4j + k$, then $\vec a \wedge \vec b$ is', '["$-2i + 4j - 10k$", "$2i + 4j + 10k$", "$-2i - 4j + 10k$", "$2i - 4j - 10k$"]'::jsonb, 0, '$(-1,2,1)\times(3,4,1) = (2\cdot1-1\cdot4,\,1\cdot3-(-1)\cdot1,\,-1\cdot4-2\cdot3) = (-2,4,-10)$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The scalar product of $4i - 3j + 5k$ and $7i - 3k$ is', '["$13$", "$17$", "$37$", "$10$"]'::jsonb, 0, '$(4)(7)+(-3)(0)+(5)(-3) = 28+0-15 = 13$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec u = 4i - 3j + 5k$, $\vec v = i + 2j + 5k$ and $\vec w = 7i - 2j$, then $(\vec u + 2\vec v)\cdot(\vec w - 2\vec v)$ is', '["$-126$", "$126$", "$26$", "$10$"]'::jsonb, 0, '$\vec u+2\vec v = 6i+j+15k$ and $\vec w-2\vec v = 5i-6j-10k$. Their dot product is $30-6-150=-126$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec a = 3i - j + 2k$, $\vec b = 2i + j - k$ and $\vec c = i - 2j + 2k$, then $(\vec a \wedge \vec b)\wedge \vec c$ is', '["$24i + 7j - 5k$", "$24i - 7j - 5k$", "$15i - 15j + 15k$", "$15i - 15j - 15k$"]'::jsonb, 0, 'First $\vec a\wedge\vec b = -i+7j+5k$. Then $(-1,7,5)\times(1,-2,2) = (14+10,\,5+2,\,2-7) = (24,7,-5)$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec a = 3i - j + 2k$, $\vec b = 2i + j - k$ and $\vec c = i - 2j + 2k$, then $\vec a \wedge (\vec b \wedge \vec c)$ is', '["$15i + 15j - 15k$", "$15i - 15j + 15k$", "$15i - 15j - 15k$", "$-15i + 15j - 15k$"]'::jsonb, 0, 'First $\vec b\wedge\vec c = (0,-5,-5)$. Then $\vec a\wedge(\vec b\wedge \vec c) = (3,-1,2)\times(0,-5,-5) = (5+10,\,0+15,\,-15-0) = (15,15,-15)$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the plane through the points $P_1(1,2,-1)$, $P_2(2,3,1)$ and $P_3(3,-1,2)$.', '["$9x + y - 5z - 16 = 0$", "$9x - y + 5z - 16 = 0$", "$9x + y + 5z - 16 = 0$", "$-9x + y - 5z + 16 = 0$"]'::jsonb, 0, 'Take $\vec{P_1P_2}=(1,1,2)$ and $\vec{P_1P_3}=(2,-3,3)$. Their cross product gives the normal $\vec n = (9,1,-5)$. Using point $P_1(1,2,-1)$: $9(x-1)+1(y-2)-5(z+1)=0 \Rightarrow 9x+y-5z-16=0$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the plane through the points $P(2,-1,1)$, $Q(3,2,-1)$ and $R(-1,3,2)$.', '["$11x + 5y + 13z = 30$", "$11x - 5y + 13z = 30$", "$11x + 5y - 13z = 30$", "$5x + 11y + 13z = 30$"]'::jsonb, 0, 'Take $\vec{PQ}=(1,3,-2)$ and $\vec{PR}=(-3,4,1)$. Their cross product gives the normal $\vec n=(11,5,13)$. Using $P(2,-1,1)$: $11(x-2)+5(y+1)+13(z-1)=0 \Rightarrow 11x+5y+13z=30$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The area of the triangle having $i + 4j + 6k$ and $i - j + k$ as adjacent sides is', '["$\\dfrac{\\sqrt{150}}{2}$ sq. units", "$3\\sqrt{120}$ sq. units", "$3\\sqrt{150}$ sq. units", "$2\\sqrt{150}$ sq. units"]'::jsonb, 0, 'Area $=\tfrac12|\vec u\wedge\vec v|$. Here $\vec u\wedge\vec v = (1,4,6)\times(1,-1,1) = (10,5,-5)$, with magnitude $\sqrt{150}$, so the area is $\sqrt{150}/2$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Triangle $ABC$ has position vectors $\vec a = i+j$, $\vec b = -i+j+5k$ and $\vec c = -2i+j+k$. Find its area.', '["$\\dfrac{13}{2}$ sq. units", "$\\dfrac{13\\sqrt3}{2}$ sq. units", "$13$ sq. units", "$13\\sqrt3$ sq. units"]'::jsonb, 0, 'Area $= \tfrac12|(\vec b-\vec a)\wedge(\vec c-\vec a)|$. Here $\vec b-\vec a=-2i+5k$ and $\vec c-\vec a=-3i+k$, whose cross product is $(0,-13,0)$, of magnitude $13$. Area $=13/2$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle with vertices $(0,0)$, $(5,2)$ and $(2,5)$.', '["$\\dfrac{21}{2}$ sq. units", "$21$ sq. units", "$\\dfrac{29}{2}$ sq. units", "$\\dfrac{19}{2}$ sq. units"]'::jsonb, 0, 'Area $=\tfrac12|x_1(y_2-y_3)+x_2(y_3-y_1)+x_3(y_1-y_2)| = \tfrac12|0(2-5)+5(5-0)+2(0-2)| = \tfrac12|25-4|=\tfrac{21}{2}$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle whose vertices are $(1,5)$, $(-3,9)$ and $(-2,8)$.', '["$0$", "$4$", "$5$", "$9$"]'::jsonb, 1, 'Area $=\tfrac12|1(9-8)+(-3)(8-5)+(-2)(5-9)| = \tfrac12|1-9+8| = 0$, so the three points are collinear.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Triangle $ABC$ has $A(2,0)$, $B(x,0)$ and $C(-1,-2)$. If its area is $1$ square unit, find $x$.', '["$1$", "$-3/2$", "$3/2$", "$-5$"]'::jsonb, 0, 'Area $=\tfrac12|x_1(y_2-y_3)+x_2(y_3-y_1)+x_3(y_1-y_2)| = \tfrac12|2(0+2)+x(-2-0)+(-1)(0-0)| = \tfrac12|4-2x|=1$. Since $B$ visibly lies left of $A$ in the figure, $x=1$ (the equation also admits $x=3$).', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle with vertices $A(2,1)$, $B(-3,0)$ and $C(-2,4)$.', '["$9\\tfrac12$", "$9$", "$18$", "$19$"]'::jsonb, 0, 'Area $=\tfrac12|2(0-4)+(-3)(4-1)+(-2)(1-0)| = \tfrac12|-8-9-2| = \tfrac{19}{2}=9\tfrac12$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $A(-2,4)$, $B(0,5)$ and $C(-1,-1)$, find $\angle ABC$.', '["$\\arctan(11/8)$", "$\\arctan(-11/3)$", "$\\arctan(-11/8)$", "$\\arctan(11/3)$"]'::jsonb, 0, 'The slope of $AB$ is $m_{AB}=(4-5)/(-2-0)=1/2$ and the slope of $BC$ is $m_{BC}=(5-(-1))/(0-(-1))=6$. Then $\tan(\angle ABC) = \dfrac{m_{BC}-m_{AB}}{1+m_{BC}m_{AB}} = \dfrac{6-1/2}{1+3} = \dfrac{11}{8}$, so $\angle ABC = \arctan(11/8)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The area of the parallelogram having $i + 4j + 6k$ and $i - j + k$ as adjacent sides is', '["$5\\sqrt6$", "$\\sqrt{62}$", "$\\dfrac{5\\sqrt6}{2}$", "$\\dfrac{5\\sqrt2}{2}$"]'::jsonb, 0, 'Area $=|\vec u\wedge \vec v|$ where $\vec u\wedge\vec v=(1,4,6)\times(1,-1,1)=(10,5,-5)$, of magnitude $\sqrt{150}=5\sqrt6$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the volume of the parallelepiped generated by the vectors $i+2j+3k$, $-i+3j+4k$ and $2i+5j+2k$.', '["$27$", "$27\\sqrt2$", "$\\sqrt{27}$", "$729$"]'::jsonb, 0, 'Volume $=|\vec A\cdot(\vec B\wedge\vec C)|$. Evaluating the $3\times3$ determinant of the three vectors gives $-27$, so the volume is $|-27|=27$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the volume of the parallelepiped with sides $\vec a = i+2j+3k$, $\vec b=4i+5j+6k$, $\vec c=7i+8j+10k$.', '["$3$", "$10$", "$36$", "$5$"]'::jsonb, 0, 'The scalar triple product $\vec a\cdot(\vec b\wedge\vec c)$ evaluates to $-3$, so the volume is $|-3|=3$.', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The value of $\lambda$ such that $(3,\lambda,0)$, $(2,-4,2)$ and $(1,2,2)$ are coplanar is', '["$-2$", "$2$", "$-4$", "$4$"]'::jsonb, 0, 'Three vectors are coplanar when their scalar triple product (the $3\times3$ determinant) is zero. Expanding $\begin{vmatrix}3&\lambda&0\\2&-4&2\\1&2&2\end{vmatrix}=0$ gives $-12-6\lambda=0$, so $\lambda=-2$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\vec a = i - j + k$, $\vec b = i + 2j - k$ and $\vec c = 3i + pj + 5k$ are coplanar, then $p$ is', '["$-6$", "$-2$", "$2$", "$6$"]'::jsonb, 0, 'Setting the scalar triple product to zero, $\begin{vmatrix}1&-1&1\\1&2&-1\\3&p&5\end{vmatrix}=0$, gives $p=-6$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $t$ are the vectors $\vec U=(-1,1,1)$, $\vec V=(-1,4,1)$ and $\vec W=(1,2,t)$ linearly dependent?', '["$-1$", "$0$", "$1$", "$2$"]'::jsonb, 0, 'Three vectors are linearly dependent exactly when their scalar triple product is zero: $\vec U\cdot(\vec V\wedge\vec W)=\begin{vmatrix}-1&1&1\\-1&4&1\\1&2&t\end{vmatrix}=0$. Expanding gives $-3t-3=0$, so $t=-1$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $t$ do $i-j+k$, $2i+j-k$ and $ti-j+tk$ lie in the same plane (coplanar)?', '["$1$", "$-1$", "$2$", "$-2$"]'::jsonb, 0, 'Coplanarity requires the scalar triple product to vanish: $\begin{vmatrix}1&-1&1\\2&1&-1\\t&-1&t\end{vmatrix}=0$. Expanding and simplifying gives $t=1$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\alpha$ such that $\vec a=i+2j+3k$, $\vec b=i+j+k$ and $\vec c=i+\alpha j+k$ are coplanar.', '["$1$", "$3$", "$-3$", "$7$"]'::jsonb, 0, 'Setting the determinant of the three vectors to zero, $\begin{vmatrix}1&2&3\\1&1&1\\1&\alpha&1\end{vmatrix}=0$, gives $\alpha=1$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\alpha$ such that $\vec a = 3i+\alpha j$, $\vec b=2i-4j-2k$ and $\vec c=i+2j+2k$ are coplanar.', '["$-2$", "$2$", "$3$", "$7$"]'::jsonb, 0, 'Coplanarity requires $\begin{vmatrix}3&\alpha&0\\2&-4&-2\\1&2&2\end{vmatrix}=0$. Expanding gives $-8\alpha-8=0$, so $\alpha=-2$.', 'Addition of vectors, scalar multiplication and linear independence', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'How are the vectors $\vec a = i + 2j + 2k$ and $\vec b = -4i + 4j - 2k$ related?', '["They are orthogonal", "They are parallel", "They are equal", "They are coplanar with the origin only"]'::jsonb, 0, '$\vec a\cdot\vec b = (1)(-4)+(2)(4)+(2)(-2) = -4+8-4=0$, so the vectors are orthogonal (perpendicular).', 'Scalar and vector products of two vectors', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\vec r = k(1+\cos t)i + k(1+\sin t)j$, find $\left|\dfrac{d^2\vec r}{dt^2}\right|$.', '["$k$", "$k^2$", "$k(-\\cos t\\, i+\\sin t\\, j)$", "$k(\\cos t\\, i + \\sin t\\, j)$"]'::jsonb, 0, '$\dfrac{d\vec r}{dt} = -k\sin t\, i + k\cos t\, j$ and $\dfrac{d^2\vec r}{dt^2} = -k\cos t\, i - k\sin t\, j$, whose magnitude is $k\sqrt{\cos^2t+\sin^2t}=k$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The acceleration of a particle at time $t\ge0$ is $\vec a = 12\cos t\, i - 12\sin t\, j$, and the particle starts from rest. Find the magnitude of its velocity.', '["$12$", "$144$", "$2\\sqrt3$", "$-12$"]'::jsonb, 0, 'Integrating, $\vec v = 12\sin t\, i + 12\cos t\, j$ (constant of integration zero since the particle starts from rest). Then $|\vec v| = 12\sqrt{\sin^2t+\cos^2t}=12$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x=\sin3t$, $y=\cos3t$, $z=t$, find the square of the magnitude of the velocity.', '["$10$", "$17$", "$18$", "$8$"]'::jsonb, 0, '$\dot x=3\cos3t,\ \dot y=-3\sin3t,\ \dot z=1$. Then $|\vec v|^2=9\cos^23t+9\sin^23t+1=9+1=10$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle''s position is $\vec r = \sin3t\,i - e^t j - \cos3t\,k$. Find the magnitude of its velocity.', '["$\\sqrt{9+e^{2t}}$", "$3\\sqrt{1+e^{2t}}$", "$\\sqrt{81+e^{2t}}$", "$9\\sqrt{1+e^{2t}}$"]'::jsonb, 0, '$\vec v = 3\cos3t\,i - e^t j + 3\sin3t\,k$, so $|\vec v|^2 = 9\cos^23t+e^{2t}+9\sin^23t = 9+e^{2t}$, giving $|\vec v|=\sqrt{9+e^{2t}}$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $x=\sin4t$, $y=\cos4t$, $z=t$, find the square of the magnitude of the velocity.', '["$17$", "$10$", "$18$", "$8$"]'::jsonb, 0, '$\dot x=4\cos4t,\ \dot y=-4\sin4t,\ \dot z=1$. Then $|\vec v|^2=16\cos^24t+16\sin^24t+1=16+1=17$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves along $\vec r = \sin3t\,i - 3e^t j + \cos3t\,k$. Find the magnitude of its velocity.', '["$3\\sqrt{1+e^{2t}}$", "$\\sqrt{9+e^{4t}}$", "$\\sqrt{81+e^{2t}}$", "$9\\sqrt{1+e^{2t}}$"]'::jsonb, 0, '$\vec v = 3\cos3t\,i - 3e^tj-3\sin3t\,k$, so $|\vec v|^2 = 9\cos^23t+9e^{2t}+9\sin^23t = 9(1+e^{2t})$, giving $|\vec v|=3\sqrt{1+e^{2t}}$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If the acceleration of a particle is $\vec a = 12\cos2t\,i - 8\sin2t\,j$, find its velocity $\vec v$ at time $t$.', '["$6\\sin2t\\,i + 4\\cos2t\\,j + \\vec C$", "$6\\cos2t\\,i + 4\\sin2t\\,j + \\vec C$", "$6\\sin t\\,i+4\\cos t\\,j+\\vec C$", "$\\sin2t\\,i+\\cos2t\\,j+\\vec C$"]'::jsonb, 0, 'Integrate each component: $\int 12\cos2t\,dt = 6\sin2t$ and $\int -8\sin2t\,dt = 4\cos2t$, so $\vec v = 6\sin2t\,i+4\cos2t\,j+\vec C$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves along $x=e^t$, $y=2\cos3t$, $z=2\sin3t$. Find its velocity vector.', '["$e^t i - 6\\sin3t\\,j + 6\\cos3t\\,k$", "$e^t i + 6\\sin3t\\,j+6\\cos3t\\,k$", "$e^t i - 6\\sin3t\\,j - 6\\cos3t\\,k$", "$e^t i - 2\\sin3t\\,j+6\\cos3t\\,k$"]'::jsonb, 0, 'Differentiate each component with respect to $t$: $\dot x=e^t,\ \dot y=-6\sin3t,\ \dot z=6\cos3t$.', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the acceleration of the particle whose position vector is $\vec r = ti + 2t^2j + k$.', '["$4j$", "$4i+4j$", "$i-4j$", "$-4j$"]'::jsonb, 0, '$\vec v = \dot{\vec r} = i+4tj$, and $\vec a = \ddot{\vec r} = 4j$ (the $i$ and $k$ components have zero second derivative).', 'Differentiation and integration of vectors with respect to a scalar', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(1,3)$ and $B(4,3)$.', '["$3$", "$5$", "$\\sqrt{10}$", "$7$"]'::jsonb, 0, 'Since the $y$-coordinates are equal, the distance is just the difference of the $x$-coordinates: $|4-1|=3$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(1,2)$ and $B(4,6)$.', '["$5$", "$\\sqrt{5}$", "$25$", "$\\sqrt{29}$"]'::jsonb, 0, '$d=\sqrt{(4-1)^2+(6-2)^2}=\sqrt{9+16}=\sqrt{25}=5$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(-4,-3)$ and $B(5,7)$.', '["$\\sqrt{181}$", "$181$", "$\\sqrt{171}$", "$19$"]'::jsonb, 0, '$d=\sqrt{(5-(-4))^2+(7-(-3))^2}=\sqrt{81+100}=\sqrt{181}$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Points $A(5,1)$ and $B(8,-3)$ are given. Find $|AB|$.', '["$5$", "$\\sqrt5$", "$4$", "$\\sqrt5/2$"]'::jsonb, 0, '$|AB|=\sqrt{(8-5)^2+(-3-1)^2}=\sqrt{9+16}=\sqrt{25}=5$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Let $P(a,b)$, $Q(-a,-b)$ and $O(0,0)$ be three points, with $a,b$ not both zero. Which statement is true in general?', '["$|OP| = |OQ|$", "$|PQ| = |OQ|$", "$|OP| = |PQ|$", "All of the above"]'::jsonb, 0, '$|OP|=\sqrt{a^2+b^2}$ and $|OQ|=\sqrt{(-a)^2+(-b)^2}=\sqrt{a^2+b^2}$, so $|OP|=|OQ|$. But $|PQ|=\sqrt{(2a)^2+(2b)^2}=2\sqrt{a^2+b^2}=2|OP|\neq|OQ|$ in general.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the values of $x$ for which the points $A(x,1)$ and $B(0,-3)$ are equidistant from the point $C(5,-3)$.', '["$x=2$ or $x=8$", "$x=-2$ or $x=8$", "$x=2$ or $x=-8$", "$x=-2$ or $x=-8$"]'::jsonb, 0, 'Setting $|CA|^2=|CB|^2$: $(5-x)^2+16=25+0$, so $(5-x)^2=9$, giving $5-x=\pm3$, i.e. $x=2$ or $x=8$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the points that divide the line segment joining $A(5,-2)$ and $B(6,3)$ into three equal parts.', '["$\\left(\\dfrac{16}{3},-\\dfrac13\\right)$ and $\\left(\\dfrac{17}{3},\\dfrac43\\right)$", "$\\left(\\dfrac{17}{3},\\dfrac43\\right)$ and $\\left(\\dfrac{16}{3},-\\dfrac13\\right) \\text{ swapped}$", "$(5.5,0.5)$ and $(5.5,0.5)$", "$\\left(\\dfrac{16}{3},\\dfrac13\\right)$ and $\\left(\\dfrac{17}{3},-\\dfrac43\\right)$"]'::jsonb, 0, 'The point dividing $AB$ in ratio $1:2$ is $\left(\dfrac{2(5)+6}{3},\dfrac{2(-2)+3}{3}\right)=\left(\dfrac{16}{3},-\dfrac13\right)$, and the point dividing it in ratio $2:1$ is $\left(\dfrac{5+2(6)}{3},\dfrac{-2+2(3)}{3}\right)=\left(\dfrac{17}{3},\dfrac43\right)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', '$ABCD$ is a parallelogram with $A(0,-2)$, $B(8,1)$ and $C(4,8)$. Find the coordinates of $D$.', '["$(-4,5)$", "$(4,5)$", "$(-4,-5)$", "$(12,11)$"]'::jsonb, 0, 'In a parallelogram the diagonals bisect each other, so the midpoint of $AC$ equals the midpoint of $BD$: $D = A + C - B = (0+4-8,\,-2+8-1) = (-4,5)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Point $P$ divides the segment joining $A(2,4)$ and $B(8,10)$ internally in the ratio $2:1$. Find $P$.', '["$(6,8)$", "$(4,6)$", "$(5,7)$", "$(7,9)$"]'::jsonb, 0, '$P=\left(\dfrac{2(8)+1(2)}{3},\dfrac{2(10)+1(4)}{3}\right) = (6,8)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Point $Q$ divides the segment joining $A(3,5)$ and $B(9,11)$ externally in the ratio $2:1$. Find $Q$.', '["$(15,17)$", "$(12,14)$", "$(9,11)$", "$(6,8)$"]'::jsonb, 0, 'For external division, $Q=\left(\dfrac{2(9)-1(3)}{2-1},\dfrac{2(11)-1(5)}{2-1}\right) = (15,17)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the point $P$ that divides the segment joining $(1,2)$ and $(4,7)$ internally in the ratio $2:3$.', '["$\\left(\\dfrac{11}{5},4\\right)$", "$\\left(\\dfrac74,\\dfrac{15}{4}\\right)$", "$\\left(\\dfrac85,3\\right)$", "$\\left(\\dfrac{17}{8},\\dfrac{31}{8}\\right)$"]'::jsonb, 0, '$P=\left(\dfrac{2(4)+3(1)}{5},\dfrac{2(7)+3(2)}{5}\right)=\left(\dfrac{11}{5},4\right)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the point $P$ that divides the segment joining $(1,2)$ and $(4,7)$ internally in the ratio $1:4$.', '["$\\left(\\dfrac85,3\\right)$", "$\\left(\\dfrac{11}{5},4\\right)$", "$\\left(\\dfrac74,\\dfrac{15}4\\right)$", "$\\left(\\dfrac{17}{8},\\dfrac{31}{8}\\right)$"]'::jsonb, 0, '$P=\left(\dfrac{1(4)+4(1)}{5},\dfrac{1(7)+4(2)}{5}\right)=\left(\dfrac85,3\right)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A point $P$ divides the segment joining $(k,-k)$ and $(2k,3k)$ internally in the ratio $2k:4k$. Find $P$ in terms of $k$.', '["$\\left(\\dfrac{4k}{3},\\dfrac{k}{3}\\right)$", "$\\left(\\dfrac{5k}{3},\\dfrac{5k}{3}\\right)$", "$\\left(\\dfrac{7k}{3},\\dfrac{3k}{3}\\right)$", "$\\left(\\dfrac{8k}{3},\\dfrac{7k}{3}\\right)$"]'::jsonb, 0, 'The ratio $2k:4k$ simplifies to $1:2$. $P=\left(\dfrac{1(2k)+2(k)}{3},\dfrac{1(3k)+2(-k)}{3}\right) = \left(\dfrac{4k}{3},\dfrac{k}{3}\right)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance of the point $(-2,-1)$ from the line $3x+4y=0$.', '["$2$", "$5/4$", "$4/5$", "$-4/5$"]'::jsonb, 0, '$d=\dfrac{|3(-2)+4(-1)|}{\sqrt{3^2+4^2}}=\dfrac{10}{5}=2$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $A(-1,1)$, $B(3,3)$ and $C(1,-1)$, what type of triangle is $ABC$?', '["Isosceles", "Scalene", "Right-angled", "Equilateral"]'::jsonb, 0, '$|AB|=\sqrt{16+4}=2\sqrt5$, $|BC|=\sqrt{4+16}=2\sqrt5$ and $|AC|=\sqrt{4+4}=2\sqrt2$. Since $|AB|=|BC|\ne|AC|$, the triangle is isosceles (checking the dot products at each vertex shows no right angle).', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(c,d)$ and $B(d,c)$.', '["$\\sqrt2\\,|c-d|$", "$|c-d|$", "$2|c-d|$", "$\\sqrt2\\,(c+d)$"]'::jsonb, 0, '$|AB|=\sqrt{(d-c)^2+(c-d)^2}=\sqrt{2(c-d)^2}=\sqrt2\,|c-d|$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the line joining the points on the curve $y=3x^2-2x+1$ whose $x$-coordinates are $-1$ and $2$.', '["$1$", "$3$", "$-1$", "$5$"]'::jsonb, 0, 'At $x=-1$: $y=3+2+1=6$. At $x=2$: $y=12-4+1=9$. Gradient $=\dfrac{9-6}{2-(-1)}=\dfrac{3}{3}=1$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(-3,5)$ perpendicular to $x+y+16=0$.', '["$y-x-8=0$", "$y-x+3=0$", "$y-x+8=0$", "$y+x-2=0$"]'::jsonb, 0, 'The given line has slope $-1$, so the perpendicular has slope $1$. Through $(-3,5)$: $y-5=1(x+3)$, giving $y-x-8=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(2,1)$ perpendicular to $3x-4y+2=0$.', '["$4x+3y-11=0$", "$4x-3y+11=0$", "$3x+4y-11=0$", "$3x-4y-11=0$"]'::jsonb, 0, 'The given line has slope $3/4$, so the perpendicular has slope $-4/3$. Through $(2,1)$: $y-1=-\tfrac43(x-2)$, giving $4x+3y-11=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through the points $(-2,3)$ and $(4,2)$.', '["$x+6y-16=0$", "$x-6y+16=0$", "$6x+y-16=0$", "$x+6y+16=0$"]'::jsonb, 0, 'Slope $=\dfrac{2-3}{4-(-2)}=-\dfrac16$. Through $(-2,3)$: $y-3=-\tfrac16(x+2)$, which simplifies to $x+6y-16=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation, in general form, of the line through $A(-4,-1)$ and $B(2,-3)$.', '["$x+3y+7=0$", "$x-3y+7=0$", "$3x+y+7=0$", "$x+3y-7=0$"]'::jsonb, 0, 'Slope $=\dfrac{-3-(-1)}{2-(-4)}=-\dfrac13$. Through $(-4,-1)$: $y+1=-\tfrac13(x+4)$, giving $x+3y+7=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $l$ and $m$ if $lx+my+5=0$ represents the same straight line as $2y-3x+1=0$.', '["$l=-15,\\ m=10$", "$l=10,\\ m=-15$", "$l=15,\\ m=-10$", "$l=-10,\\ m=15$"]'::jsonb, 0, 'Rewrite the second line as $-3x+2y+1=0$. Matching coefficients proportionally with $lx+my+5=0$: $\dfrac{l}{-3}=\dfrac{m}{2}=\dfrac{5}{1}=5$, so $l=-15$ and $m=10$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(-1,-2)$ making an angle of $30^\circ$ with the positive $x$-axis.', '["$x-\\sqrt3y+1-2\\sqrt3=0$", "$x+\\sqrt3y+1-2\\sqrt3=0$", "$\\sqrt3x-y+1-2\\sqrt3=0$", "$x-\\sqrt3y-1+2\\sqrt3=0$"]'::jsonb, 0, 'The slope is $\tan30^\circ=1/\sqrt3$. Through $(-1,-2)$: $y+2=\tfrac{1}{\sqrt3}(x+1)$. Multiplying by $\sqrt3$ and rearranging gives $x-\sqrt3y+1-2\sqrt3=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of a line with $x$-intercept $-\dfrac32$ and $y$-intercept $7$.', '["$14x-3y+21=0$", "$14x+3y-21=0$", "$3x-14y+21=0$", "$14x-3y-21=0$"]'::jsonb, 0, 'Using the intercept form $\dfrac{x}{-3/2}+\dfrac{y}{7}=1$, i.e. $-\tfrac23x+\tfrac17y=1$. Multiplying through by $21$ gives $-14x+3y=21$, i.e. $14x-3y+21=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the straight line with intercepts $4$ and $-2$ on the $x$- and $y$-axes respectively.', '["$x-2y=4$", "$x+2y=4$", "$x+2y=-1$", "$2x-y=4$"]'::jsonb, 0, 'Intercept form: $\dfrac x4+\dfrac{y}{-2}=1$. Multiplying by $4$: $x-2y=4$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(2,-1)$ with slope $2/3$.', '["$2x-3y-7=0$", "$2x-3y+7=0$", "$2x+3y-7=0$", "$3x-2y-7=0$"]'::jsonb, 0, '$y-(-1)=\tfrac23(x-2)$, which simplifies to $3y+3=2x-4$, i.e. $2x-3y-7=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line passing through $(3,-7)$ and $(-2,-5)$.', '["$2x+5y+29=0$", "$2x-5y+29=0$", "$5x+2y+29=0$", "$2x+5y-29=0$"]'::jsonb, 0, 'Slope $=\dfrac{-5-(-7)}{-2-3}=-\dfrac25$. Through $(3,-7)$: $y+7=-\tfrac25(x-3)$, which simplifies to $2x+5y+29=0$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through the points $(0,2a)$ and $(2a,0)$.', '["$x+y=2a$", "$x+y=4a$", "$x-y=2a$", "$x+y=0$"]'::jsonb, 0, 'Using the intercept form $\dfrac{x}{2a}+\dfrac{y}{2a}=1$ gives $x+y=2a$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through the points $(a,0)$ and $(0,b)$.', '["$ay+bx=ab$", "$ay-bx=ab$", "$y+x=b$", "$x+y=a$"]'::jsonb, 0, 'Intercept form $\dfrac xa+\dfrac yb=1$; multiplying by $ab$ gives $bx+ay=ab$, i.e. $ay+bx=ab$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Which of these lines belong to the same family (i.e. are parallel)? (I) $3x+2y+4=0$ (II) $2x+3y-7=0$ (III) $3x+2y-4=0$ (IV) $3x-2y+6=0$', '["I and III", "II, III and IV", "I and IV", "II and IV"]'::jsonb, 0, 'Lines (I) and (III) both have slope $-3/2$ (they differ only in the constant term), so they are parallel and belong to the same family.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The angle between two lines is $\pi/4$, and the slope of one of them is $1/2$. Find the slope of the other.', '["$3$", "$-1/3$", "$2$", "$-2$"]'::jsonb, 0, 'Using $\tan\theta=\left|\dfrac{m_2-m_1}{1+m_1m_2}\right|$ with $m_1=1/2$ and $\theta=\pi/4$: $\left|\dfrac{m_2-1/2}{1+m_2/2}\right|=1$, giving $m_2=3$ or $m_2=-1/3$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The line through $(-2,6)$ and $(4,8)$ is perpendicular to the line through $(8,12)$ and $(\lambda,24)$. Find $\lambda$.', '["$4$", "$-4$", "$8$", "$-8$"]'::jsonb, 0, 'Slope of the first line: $m_1=\dfrac{8-6}{4-(-2)}=\dfrac13$. For perpendicularity, the second slope must be $-3$: $\dfrac{24-12}{\lambda-8}=-3 \Rightarrow 12=-3(\lambda-8)\Rightarrow \lambda=4$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the straight line through $(1,-2)$ and parallel to $2x+3y+4=0$.', '["$2x+3y+4=0$", "$2x+3y-4=0$", "$3x+2y+4=0$", "$2x-3y+4=0$"]'::jsonb, 0, 'A line parallel to $2x+3y+4=0$ has the form $2x+3y+k=0$. Substituting $(1,-2)$: $2-6+k=0\Rightarrow k=4$, giving $2x+3y+4=0$ (the required line coincides with the given one, since $(1,-2)$ lies on it).', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the angle between the straight lines $y-\sqrt3x-5=0$ and $\sqrt3y-x+6=0$.', '["$30^\\circ$", "$\\tan^{-1}(1/6)$", "$\\tan^{-1}(1/2)$", "$60^\\circ$"]'::jsonb, 0, 'Line 1 has slope $\sqrt3$; line 2, rewritten as $y=\tfrac{1}{\sqrt3}x-2\sqrt3$, has slope $1/\sqrt3$. $\tan\theta=\left|\dfrac{\sqrt3-1/\sqrt3}{1+1}\right|=\dfrac{1}{\sqrt3}$, so $\theta=30^\circ$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $k$ for which the lines $3x+4y=5$ and $4x+ky=2$ are perpendicular.', '["$-3$", "$3$", "$4$", "$12$"]'::jsonb, 0, 'Slopes are $-3/4$ and $-4/k$. Perpendicularity requires $\left(-\tfrac34\right)\left(-\tfrac4k\right)=-1 \Rightarrow \tfrac3k=-1 \Rightarrow k=-3$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the normal to the curve $xy=4$ at the point $(4,1)$.', '["$y-4x+15=0$", "$4y+x=8$", "$4x-y+13=0$", "$y-4x=8$"]'::jsonb, 0, 'Differentiating $xy=4$ implicitly: $x\,dy/dx+y=0$, so $dy/dx=-y/x$. At $(4,1)$, the tangent slope is $-1/4$, so the normal slope is $4$. The normal is $y-1=4(x-4)$, i.e. $y-4x+15=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the acute angle between the lines $x=1$ and $y-x=8$.', '["$\\pi/4$", "$\\pi/2$", "$\\pi/3$", "$\\pi$"]'::jsonb, 0, 'The line $x=1$ is vertical; the line $y=x+8$ makes a $45^\circ$ angle with the $x$-axis. The acute angle between a vertical line and a $45^\circ$ line is $90^\circ-45^\circ=45^\circ=\pi/4$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the point of intersection of the straight lines $4x+3y=10$ and $3x+5y=13$.', '["$(1,2)$", "$(3,5)$", "$(1,-1)$", "$(2,1)$"]'::jsonb, 0, 'Solving simultaneously: multiplying the first by $5$ and the second by $3$ gives $20x+15y=50$ and $9x+15y=39$; subtracting, $11x=11\Rightarrow x=1$, and then $y=2$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance of the origin from the line $4x+3y+10=0$.', '["$2$", "$25$", "$5$", "$2/5$"]'::jsonb, 0, '$d=\dfrac{|4(0)+3(0)+10|}{\sqrt{16+9}}=\dfrac{10}{5}=2$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance between the point $(-2,3)$ and the line $4x-3y=8$.', '["$5$", "$3/2$", "$-5$", "$5/3$"]'::jsonb, 0, '$d=\dfrac{|4(-2)-3(3)-8|}{\sqrt{16+9}}=\dfrac{|-25|}{5}=5$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the two parallel lines $3x+4y-7=0$ and $3x+4y+13=0$.', '["$4$", "$0$", "$6/5$", "$5$"]'::jsonb, 0, 'Take the point $(5,-2)$ on the first line (checking $3(5)+4(-2)-7=15-8-7=0$). Its distance to the second line is $\dfrac{|3(5)+4(-2)+13|}{5}=\dfrac{20}{5}=4$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance of the point $(-3,2)$ from the line joining $(-2,-4)$ and $(2,-6)$.', '["$11/\\sqrt5$", "$3$", "$6$", "$3\\sqrt5/2$"]'::jsonb, 0, 'The line through $(-2,-4)$ and $(2,-6)$ has equation $x+2y+10=0$. The distance from $(-3,2)$ is $\dfrac{|1(-3)+2(2)+10|}{\sqrt5}=\dfrac{11}{\sqrt5}$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(-1,-2)$ and $B(-4,3)$.', '["$\\sqrt{34}$", "$34$", "$\\sqrt{29}$", "$\\sqrt{13}$"]'::jsonb, 0, '$|AB|=\sqrt{(-4-(-1))^2+(3-(-2))^2}=\sqrt{9+25}=\sqrt{34}$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle with vertices $A(1,4)$, $B(-2,8)$ and $C(-7,-7)$.', '["$32.5$ sq. units", "$65$ sq. units", "$16.25$ sq. units", "$27$ sq. units"]'::jsonb, 0, 'Area $=\tfrac12|1(8-(-7))+(-2)(-7-4)+(-7)(4-8)| = \tfrac12|15+22+28| = \tfrac12(65)=32.5$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the quadrilateral $ABCD$ with vertices $A(3,-3)$, $B(4,4)$, $C(-4,3)$ and $D(-2,-3)$ (taken in order).', '["$42.5$ sq. units", "$21.25$ sq. units", "$45$ sq. units", "$38$ sq. units"]'::jsonb, 0, 'Using the shoelace formula on the vertices in order, $\text{Area}=\tfrac12\left|\sum (x_iy_{i+1}-x_{i+1}y_i)\right| = \tfrac12(85) = 42.5$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A pentagon has vertices $P(4,2)$, $Q(-2,8)$, $R(-6,-4)$, $S(1,-11)$ and $T(8,-1)$. Find its area.', '["$134.5$ sq. units", "$67.25$ sq. units", "$120$ sq. units", "$142$ sq. units"]'::jsonb, 0, 'Applying the shoelace formula to the five vertices in order gives an area of $134.5$ square units.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A hexagon has vertices $A(0,0)$, $B(-2,8)$, $C(-5,-5)$, $D(0,-1)$, $E(5,-8)$ and $F(7,-1)$. Find its area.', '["$55.5$ sq. units", "$111$ sq. units", "$60$ sq. units", "$48.5$ sq. units"]'::jsonb, 0, 'Applying the shoelace formula to the six vertices in order gives an area of $55.5$ square units.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centroid of the triangle with vertices $A(3,6)$, $B(-1,-1)$ and $C(4,1)$.', '["$(2,2)$", "$(-2,-2)$", "$(6,6)$", "$(3,3)$"]'::jsonb, 0, 'Centroid $=\left(\dfrac{3-1+4}{3},\dfrac{6-1+1}{3}\right) = (2,2)$.', 'Two-dimensional coordinate geometry and the straight line', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Which of the following is an example of a conic section?', '["A circle", "A square", "A rectangle", "A triangle"]'::jsonb, 0, 'A conic section (circle, parabola, ellipse or hyperbola) is a curve obtained from the intersection of a plane with a cone. A circle is a conic section; squares, rectangles and triangles are not.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A conic section with eccentricity $e=\tfrac12$ is a(n)', '["Ellipse", "Circle", "Parabola", "Hyperbola"]'::jsonb, 0, 'For a conic, $e<1$ describes an ellipse, $e=1$ a parabola, $e>1$ a hyperbola, and $e=0$ a circle. Since $1/2<1$, the conic is an ellipse.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The eccentricity of a circle is', '["$0$", "$1$", "$1/2$", "Undefined"]'::jsonb, 0, 'A circle is the special case of an ellipse with equal foci, i.e. eccentricity $e=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The curve $xy=1$ represents a', '["Hyperbola", "Ellipse", "Circle", "Parabola"]'::jsonb, 0, 'Writing $xy-1=0$ in general conic form $ax^2+bxy+cy^2+dx+ey+f=0$ gives $a=c=0,\ b=1$, so $b^2-4ac=1>0$, which is the condition for a hyperbola.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The equation $ax^2+by^2+cx+dy+e=0$ (with no $xy$ term) represents a parabola if and only if', '["$ab=0$", "$ab>0$", "$ab<0$", "$a=b$"]'::jsonb, 0, 'Here the coefficient of $xy$ is $b_{xy}=0$, so the discriminant condition $b_{xy}^2-4ac=0$ for a parabola becomes $-4ab=0$, i.e. $ab=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle whose centre is at $(3,-7)$ and whose radius is $2$.', '["$(x-3)^2+(y+7)^2=4$", "$(x+3)^2+(y-7)^2=4$", "$(x-3)^2+(y+7)^2=2$", "$(x-7)^2+(y+3)^2=4$"]'::jsonb, 0, 'The standard equation of a circle with centre $(h,k)$ and radius $r$ is $(x-h)^2+(y-k)^2=r^2$. Here that gives $(x-3)^2+(y+7)^2=4$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centre and radius of the circle $3x^2+3y^2-6x-9y-1=0$.', '["Centre $(1,\\tfrac32)$, radius $\\sqrt{43/12}$", "Centre $(1,-\\tfrac32)$, radius $\\sqrt{43/12}$", "Centre $(-1,\\tfrac32)$, radius $\\sqrt{43/12}$", "Centre $(1,\\tfrac32)$, radius $43/12$"]'::jsonb, 0, 'Dividing by $3$: $x^2+y^2-2x-3y-\tfrac13=0$. Completing the square: $(x-1)^2+(y-\tfrac32)^2 = \tfrac13+1+\tfrac94=\tfrac{43}{12}$. So the centre is $(1,\tfrac32)$ and the radius is $\sqrt{43/12}$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', '$C(-5,3)$ is a fixed point, and $P(x,y)$ moves so that its distance from $C$ is always $2$ units. Find the equation of the locus of $P$.', '["$x^2+y^2+10x-6y+30=0$", "$x^2+y^2-10x+6y+30=0$", "$x^2+y^2+10x-6y-30=0$", "$x^2+y^2+10x+6y+30=0$"]'::jsonb, 0, 'The locus is the circle $(x+5)^2+(y-3)^2=4$, which expands to $x^2+y^2+10x-6y+34-4=0$, i.e. $x^2+y^2+10x-6y+30=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Where does the point $(3,1)$ lie relative to the circle $4x^2+4y^2-3x-8y-1=0$?', '["Outside the circle", "Inside the circle", "On the circle", "Cannot be determined"]'::jsonb, 0, 'Substituting $(3,1)$ into $f(x,y)=4x^2+4y^2-3x-8y-1$ gives $f(3,1)=36+4-9-8-1=22\ne0$. Since $f(3,1)>0$, the point lies outside the circle.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle having centre $(-1,0)$ and radius $2$.', '["$x^2+y^2+2x-3=0$", "$x^2+y^2-2y=0$", "$x^2+y^2+2y+1=0$", "$x^2+y^2+2x+1=0$"]'::jsonb, 0, '$(x+1)^2+y^2=4$ expands to $x^2+2x+1+y^2=4$, i.e. $x^2+y^2+2x-3=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centre and radius of the circle $x^2+y^2-14x-6y-111=0$.', '["Centre $(7,3)$, radius $13$", "Centre $(3,7)$, radius $13$", "Centre $(7,3)$, radius $\\sqrt{13}$", "Centre $(-7,-3)$, radius $13$"]'::jsonb, 0, 'Completing the square: $(x-7)^2+(y-3)^2 = 111+49+9=169=13^2$, so the centre is $(7,3)$ and the radius is $13$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle with centre $\left(\tfrac12,\tfrac12\right)$ and radius $\tfrac12\sqrt2$.', '["$x^2+y^2-x-y=0$", "$x^2+y^2+x+y=0$", "$x^2+y^2-x-y+4=0$", "$x^2+y^2-x-y-2=0$"]'::jsonb, 0, '$(x-\tfrac12)^2+(y-\tfrac12)^2=\tfrac12$ expands to $x^2-x+\tfrac14+y^2-y+\tfrac14=\tfrac12$, i.e. $x^2+y^2-x-y=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the diameter of the circle $x^2+y^2+4x-4y=1$.', '["$6$", "$3$", "$9$", "$27$"]'::jsonb, 0, 'Completing the square: $(x+2)^2+(y-2)^2=1+4+4=9$, so the radius is $3$ and the diameter is $6$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle whose diameter has endpoints $A(-1,2)$ and $B(2,-3)$.', '["$x^2+y^2-x+y-8=0$", "$x^2+y^2-x-y+8=0$", "$x^2+y^2+x+y+8=0$", "$x^2+y^2-x-y-8=0$"]'::jsonb, 0, 'Using $(x-x_1)(x-x_2)+(y-y_1)(y-y_2)=0$: $(x+1)(x-2)+(y-2)(y+3)=0$, which expands to $x^2+y^2-x+y-8=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $k$ does the line $3x+4y+k=0$ form a diameter of the circle $x^2+y^2+8x+6y+c=0$ for every value of $c$?', '["$24$", "$15$", "$-24$", "$-15$"]'::jsonb, 0, 'The circle''s centre is $(-4,-3)$ regardless of $c$. For the line to be a diameter it must pass through the centre: $3(-4)+4(-3)+k=0 \Rightarrow -24+k=0 \Rightarrow k=24$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the diameter of the circle $2x^2+2y^2+8x-8y-34=0$.', '["$10$", "$5$", "$3$", "$6$"]'::jsonb, 0, 'Dividing by 2 and completing the square: $(x+2)^2+(y-2)^2=17+4+4=25$, so the radius is $5$ and the diameter is $10$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle whose diameter has endpoints $(-1,3)$ and $(5,7)$.', '["$x^2+y^2-4x-10y+16=0$", "$x^2+y^2+2x-5y+3=0$", "$x^2+y^2-2x-5y+3=0$", "$x^2+y^2-2x-5y-3=0$"]'::jsonb, 0, 'The centre is the midpoint $(2,5)$ and the radius is $\tfrac12|(-1,3)-(5,7)|=\sqrt{13}$. So $(x-2)^2+(y-5)^2=13$, which expands to $x^2+y^2-4x-10y+16=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle whose diameter has endpoints $(1,-1)$ and $(-1,-1)$.', '["$x^2+y^2+2y=0$", "$x^2+y^2-2=0$", "$x^2+y^2+2y-12=0$", "$x^2+y^2=2$"]'::jsonb, 0, 'Using $(x-1)(x+1)+(y+1)(y+1)=0$: $x^2-1+(y+1)^2=0 \Rightarrow x^2+y^2+2y=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle whose diameter has endpoints $(0,0)$ and $(2,2)$.', '["$x^2+y^2-2x-2y=0$", "$x^2+y^2+2x+2y=0$", "$x^2+y^2-2x+2y=0$", "$x^2+y^2-2x+4y=0$"]'::jsonb, 0, 'Using $(x-0)(x-2)+(y-0)(y-2)=0$: $x^2-2x+y^2-2y=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the chord of contact to the circle $x^2+y^2=5$ from the external point $(-5,-5)$.', '["$x+y+1=0$", "$x-y-1=0$", "$x+y-1=0$", "$y-x+1=0$"]'::jsonb, 0, 'The chord of contact from $(x_1,y_1)$ to $x^2+y^2=r^2$ is $xx_1+yy_1=r^2$: $-5x-5y=5$, i.e. $x+y+1=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle that passes through the origin, with $x$-intercept $3$ and $y$-intercept $-2$.', '["$x^2+y^2-3x+2y=0$", "$x^2+y^2+3x-2y=0$", "$x^2+y^2-2x+3y=0$", "$x^2+y^2+2x-3y=0$"]'::jsonb, 0, 'Let the circle be $x^2+y^2+Dx+Ey+F=0$. Through the origin, $F=0$. Through $(3,0)$: $9+3D=0\Rightarrow D=-3$. Through $(0,-2)$: $4-2E=0\Rightarrow E=2$. So the circle is $x^2+y^2-3x+2y=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle passing through the points $A(2,6)$, $B(4,-2)$ and $C(-2,2)$.', '["$5x^2+5y^2-22x-18y-48=0$", "$5x^2+5y^2+22x-18y+48=0$", "$5x^2+5y^2-22x+18y+48=0$", "$5x^2-5y^2-22x-18y+48=0$"]'::jsonb, 0, 'Substituting the three points into the general circle equation $x^2+y^2+2hx+2ky+d=0$ and solving the resulting simultaneous equations gives $5x^2+5y^2-22x-18y-48=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle passing through the points $A(0,0)$, $B(5,0)$ and $C(0,6)$.', '["$x^2+y^2-5x-6y=0$", "$x^2+y^2+5x+6y=0$", "$x^2+y^2-6x-5y=0$", "$x^2+y^2-5x+6y=0$"]'::jsonb, 0, 'Since $A$ is the origin, the constant term is zero. Substituting $B(5,0)$ and $C(0,6)$ into $x^2+y^2+Dx+Ey=0$ gives $D=-5$ and $E=-6$, so the circle is $x^2+y^2-5x-6y=0$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent to the circle $x^2+y^2=7$ at the point $(0,\sqrt7)$.', '["$0$", "Undefined", "$\\sqrt7$", "$-\\sqrt7$"]'::jsonb, 0, 'Differentiating implicitly, $2x+2y\,dy/dx=0\Rightarrow dy/dx=-x/y$. At $(0,\sqrt7)$ this gives $dy/dx=0$, so the tangent is the horizontal line $y=\sqrt7$ with slope $0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to the circle $x^2+y^2=7$ at the point $(0,\sqrt7)$.', '["$y=\\sqrt7$", "$x=\\sqrt7$", "$x+y=\\sqrt7$", "$x=-\\sqrt7$"]'::jsonb, 0, 'The radius to $(0,\sqrt7)$ is vertical, so the tangent there is horizontal: $y=\sqrt7$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the slopes of the tangents drawn from the point $(-2,11)$ to the circle $x^2+y^2=25$.', '["$-4/3$ and $24/7$", "$4/3$ and $7/24$", "$-7/24$ and $4/3$", "$3/4$ and $7/24$"]'::jsonb, 0, 'A line $y=mx+2m+11$ through $(-2,11)$ meets $x^2+y^2=25$ tangentially when the resulting quadratic in $x$ has a repeated root. Solving the discriminant condition gives $21m^2-44m-96=0$, whose roots are $m=-4/3$ and $m=24/7$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent and normal to the circle $x^2+y^2-10x+4y-7=0$ at the point $P(-2,3)$.', '["Tangent: $7x-5y+9=0$; Normal: $5x+7y-11=0$", "Tangent: $5x+7y-11=0$; Normal: $7x-5y+9=0$", "Tangent: $7x+5y-9=0$; Normal: $5x-7y+11=0$", "Tangent: $7x-5y-9=0$; Normal: $5x+7y+11=0$"]'::jsonb, 0, 'Using the general tangent formula $xx_1+yy_1+h(x+x_1)+k(y+y_1)+c=0$ with $h=-5,k=2,c=-7$ at $(-2,3)$ gives the tangent $7x-5y+9=0$, of slope $7/5$; the normal has slope $-5/7$ and passes through $(-2,3)$, giving $5x+7y-11=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the normal to the circle $x^2+y^2-4x-6y+3=0$ at the point $(1,2)$.', '["$3x+y-9=0$", "$x-3y+17=0$", "$x+3y-17=0$", "$3x-y-9=0$"]'::jsonb, 0, 'The tangent slope at $(1,2)$ (found by implicit differentiation) is $1/3$, so the normal slope is $-3$. The normal is $y-2=-3(x-1)$, i.e. $3x+y-9=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the tangent drawn from $P(-3,0)$ to the circle $3x^2+3y^2-12x-4y-4=0$.', '["$\\sqrt{59/3}$", "$59$", "$\\sqrt{59}$", "$\\sqrt{59}/3$"]'::jsonb, 0, 'Dividing by 3: $x^2+y^2-4x-\tfrac43y-\tfrac43=0$. Substituting $(-3,0)$ into $x^2+y^2+2hx+2ky+d$ (with unit coefficients) gives $L^2=9+0-4(-3)-\tfrac43(0)-\tfrac43 = 9+12-\tfrac43=\tfrac{59}{3}$, so $L=\sqrt{59/3}$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the tangent drawn from the point $(5,12)$ to the circle $2x^2+2y^2=50$.', '["$12$", "$5$", "$7$", "$6$"]'::jsonb, 0, 'Rewriting the circle in unit form: $x^2+y^2-25=0$. The square of the tangent length is $L^2=5^2+12^2-25=144$, so $L=12$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the tangent from the point $T(2,3)$ to the circle $2x^2+2y^2-5x-7y+6=0$.', '["$1/\\sqrt2$", "$\\sqrt3$", "$1/\\sqrt3$", "$2$"]'::jsonb, 0, 'Dividing by 2: $x^2+y^2-\tfrac52x-\tfrac72y+3=0$. Then $L^2=2^2+3^2-\tfrac52(2)-\tfrac72(3)+3 = 4+9-5-10.5+3=0.5=\tfrac12$, so $L=1/\sqrt2$.', 'Coordinate geometry of the circle', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to the circle $x^2+y^2-2x-4y-20=0$ at the point $(4,-2)$.', '["$3x-4y-20=0$", "$4x-3y-20=0$", "$3x+4y-20=0$", "$4x+3y-20=0$"]'::jsonb, 0, 'Using $xx_1+yy_1-1(x+x_1)-2(y+y_1)-20=0$ with $(x_1,y_1)=(4,-2)$: $4x-2y-(x+4)-2(y-2)-20=0$, which simplifies to $3x-4y-20=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to the circle $x^2+y^2+18x-88=0$ at the point $(3,5)$.', '["$12x+5y-61=0$", "$5x+12y-61=0$", "$12x-5y-61=0$", "$12x+5y+61=0$"]'::jsonb, 0, 'Using $xx_1+yy_1+9(x+x_1)-88=0$ with $(x_1,y_1)=(3,5)$: $3x+5y+9(x+3)-88=0$, which simplifies to $12x+5y-61=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the normal to the circle $x^2+y^2=4$ at the point $(\sqrt3,1)$.', '["$3y-\\sqrt3x=0$", "$y+\\sqrt3x=4$", "$2y-3x-1=0$", "$3y+4x-2=0$"]'::jsonb, 0, 'The normal to a circle centred at the origin always passes through the centre and the point of tangency. The line through $(0,0)$ and $(\sqrt3,1)$ has slope $1/\sqrt3$, giving $y=\tfrac{x}{\sqrt3}$, i.e. $\sqrt3y-x=0$, equivalently (multiplying by $\sqrt3$) $3y-\sqrt3x=0$.', 'Tangents and normals', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the curve consisting of all points equidistant from the line $x=-3$ and the point $(3,0)$.', '["$y^2=12x$", "$y^2=6x$", "$x^2=12y$", "$y^2=-12x$"]'::jsonb, 0, 'Setting the distance to $(3,0)$ equal to the distance to the line $x=-3$: $\sqrt{(x-3)^2+y^2}=x+3$. Squaring and simplifying, $x^2-6x+9+y^2=x^2+6x+9$, so $y^2=12x$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vertex, focus and directrix of the parabola $x^2=-6(y+4)$.', '["Vertex $(0,-4)$, focus $\\left(0,-\\tfrac{11}{2}\\right)$, directrix $y=-\\tfrac52$", "Vertex $(0,4)$, focus $\\left(0,\\tfrac{11}2\\right)$, directrix $y=\\tfrac52$", "Vertex $(-4,0)$, focus $\\left(-\\tfrac{11}2,0\\right)$, directrix $x=-\\tfrac52$", "Vertex $(0,-4)$, focus $(0,-1)$, directrix $y=-7$"]'::jsonb, 0, 'Comparing $x^2=-6(y+4)$ with $(x-h)^2=-4a(y-k)$ gives $h=0,k=-4,4a=6\Rightarrow a=\tfrac32$. So the vertex is $(0,-4)$, the focus is $(0,-4-\tfrac32)=(0,-\tfrac{11}2)$, and the directrix is $y=-4+\tfrac32=-\tfrac52$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vertex, focus and directrix of the parabola $y^2=8(x-4)$.', '["Vertex $(4,0)$, focus $(6,0)$, directrix $x=2$", "Vertex $(4,0)$, focus $(2,0)$, directrix $x=6$", "Vertex $(0,4)$, focus $(0,6)$, directrix $y=2$", "Vertex $(-4,0)$, focus $(-2,0)$, directrix $x=-6$"]'::jsonb, 0, 'Comparing with $(y-k)^2=4a(x-h)$ gives $h=4,k=0,4a=8\Rightarrow a=2$. Vertex $(4,0)$, focus $(4+2,0)=(6,0)$, directrix $x=4-2=2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vertex, focus and directrix of the parabola $y^2-8x-2y+17=0$.', '["Vertex $(2,1)$, focus $(4,1)$, directrix $x=0$", "Vertex $(1,2)$, focus $(1,4)$, directrix $y=0$", "Vertex $(2,1)$, focus $(0,1)$, directrix $x=4$", "Vertex $(-2,1)$, focus $(0,1)$, directrix $x=-4$"]'::jsonb, 0, 'Completing the square: $(y-1)^2-1-8x+17=0 \Rightarrow (y-1)^2=8x-16=8(x-2)$. So $4a=8,a=2$, vertex $(2,1)$, focus $(4,1)$, directrix $x=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The parabola $y^2=8x$ has focus and directrix', '["$F(2,0)$, $x=-2$", "$F(-2,0)$, $x=-2$", "$F(-2,1)$, $x=2$", "$F(2,0)$, $x=2$"]'::jsonb, 0, 'Comparing with $y^2=4ax$ gives $4a=8\Rightarrow a=2$. The focus is $(a,0)=(2,0)$ and the directrix is $x=-a=-2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of a parabola with vertex at the origin and focus at $\left(0,\tfrac12\right)$.', '["$x^2=2y$", "$y^2=4x$", "$4y^2=x$", "$2x^2=4y$"]'::jsonb, 0, 'For a parabola with vertex at the origin opening along the positive $y$-axis, $x^2=4ay$ with $a=\tfrac12$, giving $x^2=2y$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The focus of a parabola is at $(1,1)$ and its directrix is the line $3x+4y-2=0$. Find the length of the latus rectum.', '["$2$", "$3$", "$4$", "$1$"]'::jsonb, 0, 'The distance from the focus to the directrix equals $2a$: $2a=\dfrac{|3(1)+4(1)-2|}{\sqrt{3^2+4^2}}=\dfrac{5}{5}=1$, so $a=\tfrac12$. The latus rectum has length $4a=2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vertex of the curve $4(x+5)^2-3y+2=0$.', '["$\\left(-5,\\tfrac23\\right)$", "$\\left(5,\\tfrac23\\right)$", "$\\left(-5,-\\tfrac23\\right)$", "$\\left(-5,\\tfrac32\\right)$"]'::jsonb, 0, 'Rearranging, $y=\tfrac43(x+5)^2+\tfrac23$. This is minimised at $x=-5$, giving $y=\tfrac23$, so the vertex is $\left(-5,\tfrac23\right)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the directrix of the parabola $x^2+2x-8y-15=0$.', '["$y+4=0$", "$y=\\pm4$", "$x-y=4$", "$y+2=0$"]'::jsonb, 0, 'Completing the square: $(x+1)^2=8y+16=8(y+2)$, so $4a=8,a=2$, vertex $(-1,-2)$, and the directrix is $y=-2-2=-4$, i.e. $y+4=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the directrix of the parabola $y^2+6y-2x+5=0$.', '["$2x+5=0$", "$2x+1=0$", "$x-y=4$", "$x+5=0$"]'::jsonb, 0, 'Completing the square: $(y+3)^2=2x+4=2(x+2)$, so $4a=2,a=\tfrac12$, vertex $(-2,-3)$, and the directrix is $x=-2-\tfrac12=-\tfrac52$, i.e. $2x+5=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find a point of intersection of the parabola $y^2=4x$ and the line $x=2y-3$.', '["$(1,2)$", "$(6,9)$", "$(2,1)$", "$(4,8)$"]'::jsonb, 0, 'Substituting $x=2y-3$ into $y^2=4x$: $y^2=4(2y-3)=8y-12$, so $y^2-8y+12=0$, giving $y=6$ or $y=2$. These correspond to $(9,6)$ and $(1,2)$; the latter is listed among the options.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vertex of the parabola $y^2=2x+3$.', '["$\\left(-\\tfrac32,0\\right)$", "$(3,0)$", "$(-3,0)$", "$\\left(\\tfrac32,0\\right)$"]'::jsonb, 0, 'Rewrite as $y^2=2\left(x+\tfrac32\right)$, so the vertex is at $\left(-\tfrac32,0\right)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the directrix of the parabola $y^2-8y-2x+18=0$.', '["$2x-1=0$", "$2x-3=0$", "$x=1$", "$2x+1=0$"]'::jsonb, 0, 'Completing the square: $(y-4)^2=2x-2=2(x-1)$, so $4a=2,a=\tfrac12$, vertex $(1,4)$, and the directrix is $x=1-\tfrac12=\tfrac12$, i.e. $2x-1=0$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The parabola $y^2=4ax$ passes through the point $(2,-4)$. Find the coordinates of the focus.', '["$(2,0)$", "$(0,2)$", "$(4,0)$", "$(0,4)$"]'::jsonb, 0, 'Substituting: $16=4a(2)\Rightarrow a=2$. The focus of $y^2=4ax$ is at $(a,0)=(2,0)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the focus of the curve $(y-4)^2=2(x-1)$.', '["$\\left(\\tfrac32,4\\right)$", "$\\left(-\\tfrac32,-3\\right)$", "$\\left(1,-\\tfrac34\\right)$", "$\\left(1,\\tfrac34\\right)$"]'::jsonb, 0, 'Here $4a=2\Rightarrow a=\tfrac12$, vertex $(1,4)$, so the focus is $\left(1+\tfrac12,4\right)=\left(\tfrac32,4\right)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of a parabola with focus $(2,0)$ and directrix $x+2=0$.', '["$y^2=8x$", "$y^2=4x$", "$y^2=20x$", "$y^2=12x$"]'::jsonb, 0, 'The directrix $x=-2$ gives $a=2$ (matching the focus at $(2,0)=(a,0)$), so the parabola is $y^2=4ax=8x$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the focus of the parabola $y^2-8x-4y+12=0$.', '["$(3,2)$", "$(2,3)$", "$(-2,3)$", "$(3,-2)$"]'::jsonb, 0, 'Completing the square: $(y-2)^2=8x-8=8(x-1)$, so $4a=8,a=2$, vertex $(1,2)$, and the focus is $(1+2,2)=(3,2)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the latus rectum of the parabola $y^2-2x-2y+5=0$.', '["$2$", "$4$", "$3$", "$1$"]'::jsonb, 0, 'Completing the square: $(y-1)^2=2x-4=2(x-2)$, so $4a=2$ and the length of the latus rectum is $|4a|=2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the latus rectum of the parabola $y^2+6y-8x+5=0$.', '["$8$", "$3$", "$2$", "$4$"]'::jsonb, 0, 'Completing the square: $(y+3)^2=8x+4=8\left(x+\tfrac12\right)$, so $4a=8$, giving a latus rectum of length $8$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the ellipse with centre at the origin, one focus at $(3,0)$, and one vertex at $(4,0)$.', '["$\\dfrac{x^2}{16}+\\dfrac{y^2}{7}=1$", "$\\dfrac{x^2}{7}+\\dfrac{y^2}{16}=1$", "$\\dfrac{x^2}{16}+\\dfrac{y^2}{9}=1$", "$\\dfrac{x^2}{9}+\\dfrac{y^2}{16}=1$"]'::jsonb, 0, 'Here $a=4$ and $c=ae=3$, so $b^2=a^2-c^2=16-9=7$. The equation is $\dfrac{x^2}{16}+\dfrac{y^2}{7}=1$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Identify the conic $12x^2+8y^2+12x-24y+15=0$.', '["An ellipse", "A parabola", "A hyperbola", "A circle"]'::jsonb, 0, 'Completing the square: $12\left(x+\tfrac12\right)^2+8\left(y-\tfrac32\right)^2 = 6$, i.e. $\dfrac{(x+1/2)^2}{1/2}+\dfrac{(y-3/2)^2}{3/4}=1$. Both denominators are positive and unequal, so this is an ellipse.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the directrices of the ellipse $\dfrac{x^2}{25}+\dfrac{y^2}{16}=1$.', '["$x=\\pm\\dfrac{25}{3}$", "$x=\\pm\\dfrac{3}{25}$", "$y=\\pm\\dfrac{20}{3}$", "$y=\\pm\\dfrac{3}{25}$"]'::jsonb, 0, 'Here $a^2=25,b^2=16$, so $e=\sqrt{1-16/25}=3/5$. The directrices are $x=\pm a/e=\pm 25/3$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the foci of the ellipse $16x^2+25y^2=400$.', '["$(\\pm3,0)$", "$(0,\\pm5)$", "$(\\pm4,0)$", "$(0,\\pm3)$"]'::jsonb, 0, 'Dividing by 400: $\dfrac{x^2}{25}+\dfrac{y^2}{16}=1$, so $a^2=25,b^2=16,c^2=a^2-b^2=9\Rightarrow c=3$. The foci are $(\pm3,0)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the ellipse with centre at the origin, foci at $(0,\pm4)$ and vertices at $(0,\pm5)$.', '["$\\dfrac{x^2}{9}+\\dfrac{y^2}{25}=1$", "$\\dfrac{x^2}{25}+\\dfrac{y^2}{9}=1$", "$\\dfrac{x^2}{16}+\\dfrac{y^2}{25}=1$", "$\\dfrac{x^2}{9}+\\dfrac{y^2}{16}=1$"]'::jsonb, 0, 'The major axis is along the $y$-axis, with $a=5$ and $c=4$, so $b^2=a^2-c^2=25-16=9$. The equation is $\dfrac{x^2}{9}+\dfrac{y^2}{25}=1$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the eccentricity of the curve $4x^2+9y^2=36$.', '["$\\sqrt5/3$", "$5/7$", "$2/\\sqrt5$", "$\\sqrt5/2$"]'::jsonb, 0, 'Dividing by 36: $\dfrac{x^2}{9}+\dfrac{y^2}{4}=1$, so $a^2=9,b^2=4$, and $e=\sqrt{1-4/9}=\sqrt5/3$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the eccentricity of the ellipse $\dfrac{x^2}{9}+\dfrac{y^2}{4}=1$.', '["$\\sqrt5/3$", "$5$", "$1/2$", "$2/3$"]'::jsonb, 0, 'Here $a^2=9,b^2=4$, so $e=\sqrt{1-b^2/a^2}=\sqrt{1-4/9}=\sqrt5/3$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the latus rectum of the conic $6x^2+25y^2=100$.', '["$\\dfrac{4\\sqrt6}{5}$", "$16$", "$\\dfrac{32}{5}$", "$\\dfrac{16}{5}$"]'::jsonb, 0, 'Dividing by 100: $\dfrac{x^2}{100/6}+\dfrac{y^2}{4}=1$, so $a^2=50/3$ (major axis) and $b^2=4$. The latus rectum has length $2b^2/a = 8/\sqrt{50/3} = \dfrac{4\sqrt6}{5}$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the foci of the hyperbola $\dfrac{(y+1)^2}{4}-(x-1)^2=1$.', '["$(1,-1\\pm\\sqrt5)$", "$(-1,-1\\pm\\sqrt5)$", "$(1,1\\pm\\sqrt5)$", "$(1,-1\\pm5)$"]'::jsonb, 0, 'This has the vertical-transverse-axis form $\dfrac{(y-k)^2}{a^2}-\dfrac{(x-h)^2}{b^2}=1$ with $h=1,k=-1,a^2=4,b^2=1$. The centre is $(1,-1)$ and $c=\sqrt{a^2+b^2}=\sqrt5$, so the foci are $(h,k\pm c)=(1,-1\pm\sqrt5)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'What is the standard parametric equation of a hyperbola $\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$?', '["$x=a\\sec\\theta,\\ y=b\\tan\\theta$", "$x=a\\cos\\theta,\\ y=b\\sin\\theta$", "$x=a\\cos\\theta,\\ y=b\\tan\\theta$", "$x=a\\sin\\theta,\\ y=b\\cos\\theta$"]'::jsonb, 0, 'The identity $\sec^2\theta-\tan^2\theta=1$ matches the hyperbola equation when $x=a\sec\theta$ and $y=b\tan\theta$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the eccentricity of the conic $9x^2-4y^2=36$.', '["$\\sqrt{13}/2$", "$\\sqrt{13}/4$", "$13/4$", "$\\sqrt{13}/3$"]'::jsonb, 0, 'Dividing by 36: $\dfrac{x^2}{4}-\dfrac{y^2}{9}=1$, so $a^2=4,b^2=9$, and $e=\sqrt{1+b^2/a^2}=\sqrt{1+9/4}=\sqrt{13}/2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the eccentricity of the conic section $9x^2-4y^2+18x+8y-31=0$.', '["$\\sqrt{13}/2$", "$\\sqrt{13}/3$", "$2/\\sqrt{13}$", "$13/2$"]'::jsonb, 0, 'Completing the square: $9(x+1)^2-4(y-1)^2 = 31+9-4=36$, i.e. $\dfrac{(x+1)^2}{4}-\dfrac{(y-1)^2}{9}=1$. As before, $a^2=4,b^2=9$, giving $e=\sqrt{1+9/4}=\sqrt{13}/2$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the latus rectum of the conic $\dfrac{(x-4)^2}{9}-\dfrac{(y-4)^2}{4}=1$.', '["$8/3$", "$3$", "$8$", "$3/8$"]'::jsonb, 0, 'Here $a^2=9,b^2=4$, so $a=3$ and the latus rectum has length $2b^2/a = 8/3$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the hyperbola $\dfrac{x^2}{9}-\dfrac{y^2}{16}=1$, find the coordinates of its foci.', '["$(\\pm5,0)$", "$(0,\\pm5)$", "$(\\pm7,0)$", "$(\\pm25,0)$"]'::jsonb, 0, 'Here $a^2=9,b^2=16$, so $c=\sqrt{a^2+b^2}=\sqrt{25}=5$, and the foci are $(\pm5,0)$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equations of the asymptotes of the hyperbola $\dfrac{x^2}{9}-\dfrac{y^2}{16}=1$.', '["$y=\\pm\\dfrac43x$", "$y=\\pm\\dfrac34x$", "$y=\\pm\\dfrac59x$", "$y=\\pm x$"]'::jsonb, 0, 'For $\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$, the asymptotes are $y=\pm\dfrac{b}{a}x$. Here $a=3,b=4$, so $y=\pm\dfrac43x$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0),
  ('mth-102-vectors-geometry-dynamics', 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the eccentricity of the hyperbola $\dfrac{x^2}{9}-\dfrac{y^2}{16}=1$.', '["$5/3$", "$3/5$", "$4/3$", "$25/9$"]'::jsonb, 0, 'Here $a=3$ and $c=5$ (from the foci calculation), so $e=c/a=5/3$.', 'Conic sections: parabola, ellipse and hyperbola', false, '', 0);
